	/// <summary> Collection will display as a ComboBox in PropertyGrid on the fly. </summary>	public class SpriteAnimatedStringArrayConverter:StringConverter {		private List<string> GetSelectedObjectList() {			var keys =new List<string>();			var selObj = IUGlobal.IMainForm.PropertyGridSelectedObject();			if (selObj == null) return keys;			switch (selObj.GetType().Name) {				case "SpriteAnimated": keys = (selObj as SpriteAnimated).AnimationSetsKeys.ToList(); break;				case "SpriteAnimatedCard": keys = (selObj as SpriteAnimatedCard).AnimationKeys.ToList(); break;				case "SpriteAnimatedCage": keys = (selObj as SpriteAnimatedCage).AnimationKeys.ToList(); break;			}			return keys ?? new List<string> { };		}		public override bool GetStandardValuesSupported(ITypeDescriptorContext context) {			//true means show a combobox			return true;		}		public override bool GetStandardValuesExclusive(ITypeDescriptorContext context) {			//true will limit to list. false will show the list, but allow free-form entry			return true;		}		public override StandardValuesCollection GetStandardValues(ITypeDescriptorContext context) {			// Get string list from PropertyGrid selected object			//var sprite = context.Instance;			//var list = context.PropertyDescriptor.GetValue(sprite);			return new StandardValuesCollection(GetSelectedObjectList());		}	}